            FieldTypeMap.Add("full address", 's');
            FieldTypeMap.Add("alternate full address", 's');
            FieldTypeMap.Add("use redirection server name", 'i');
            FieldTypeMap.Add("negotiate security layer", 'i');
            FieldTypeMap.Add("enablecredsspsupport", 'i');
            FieldTypeMap.Add("disableconnectionsharing", 'i');
            FieldTypeMap.Add("autoreconnection enabled", 'i');
            FieldTypeMap.Add("gatewayhostname", 's');
            FieldTypeMap.Add("gatewayusagemethod", 'i');
            FieldTypeMap.Add("gatewayprofileusagemethod", 'i');
            FieldTypeMap.Add("gatewaycredentialssource", 'i');
            FieldTypeMap.Add("promptcredentialonce", 'i');
            FieldTypeMap.Add("alternate shell", 's');
            FieldTypeMap.Add("shell working directory", 's');
            FieldTypeMap.Add("remoteapplicationprogram", 's');
            FieldTypeMap.Add("remoteapplicationmode", 'i');
            FieldTypeMap.Add("remoteapplicationguid", 's');
            FieldTypeMap.Add("remoteapplicationname", 's');
            FieldTypeMap.Add("remoteapplicationcmdline", 's');
            FieldTypeMap.Add("loadbalanceinfo", 's');
            FieldTypeMap.Add("prompt for credentials", 'i');
            FieldTypeMap.Add("authentication level", 'i');
            FieldTypeMap.Add("audiomode", 'i');
            FieldTypeMap.Add("redirectdrives", 'i');
            FieldTypeMap.Add("redirectprinters", 'i');
            FieldTypeMap.Add("redirectcomports", 'i');
            FieldTypeMap.Add("redirectsmartcards", 'i');
            FieldTypeMap.Add("redirectposdevices", 'i');
            FieldTypeMap.Add("redirectclipboard", 'i');
