        // ---- Crypt32 P/Invoke (same as RdpCrypt.cs) --------------------------

        private const uint PKCS_7_ASN_ENCODING = 0x00010000u;
        private const uint X509_ASN_ENCODING   = 0x00000001u;
        private const uint MSG_ENCODING        = PKCS_7_ASN_ENCODING | X509_ASN_ENCODING;

        [StructLayout(LayoutKind.Sequential)]
        private struct CRYPT_OBJID_BLOB
        {
            public uint   cbData;
            public IntPtr pbData;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct CRYPT_ALGORITHM_IDENTIFIER
        {
            [MarshalAs(UnmanagedType.LPStr)] public string pszObjId;
            public CRYPT_OBJID_BLOB Parameters;
        }

        [StructLayout(LayoutKind.Sequential)]
        private struct CRYPT_SIGN_MESSAGE_PARA
        {
            public uint                   cbSize;
            public uint                   dwMsgEncodingType;
            public IntPtr                 pSigningCert;
            public CRYPT_ALGORITHM_IDENTIFIER HashAlgorithm;
            public IntPtr                 pvHashAuxInfo;
            public uint                   cMsgCert;
            public IntPtr                 rgpMsgCert;
            public uint                   cMsgCrl;
            public IntPtr                 rgpMsgCrl;
            public uint                   cAuthAttr;
            public IntPtr                 rgAuthAttr;
            public uint                   cUnauthAttr;
            public IntPtr                 rgUnauthAttr;
            public uint                   dwFlags;
            public uint                   dwInnerContentType;
            public CRYPT_ALGORITHM_IDENTIFIER HashEncryptionAlgorithm;
            public IntPtr                 pvHashEncryptionAuxInfo;
        }

        [DllImport("crypt32.dll", SetLastError = true)]
        private static extern bool CryptSignMessage(
            ref CRYPT_SIGN_MESSAGE_PARA pSignPara,
            [MarshalAs(UnmanagedType.Bool)] bool fDetachedSignature,
            uint    cToBeSigned,
            IntPtr[] rgpbToBeSigned,
            uint[]   rgcbToBeSigned,
            byte[]   pbSignedBlob,
            ref uint pcbSignedBlob
        );

        // ---- Entry point -----------------------------------------------------

        private static int Main(string[] args)
        {
            Stopwatch sw = Stopwatch.StartNew();

            try
            {
                if (args.Length < 1 || string.IsNullOrWhiteSpace(args[0]))
                {
                    Console.Error.WriteLine("RdpSignTool: ERROR: Usage: RdpSignTool.exe <path-to-rdp-file>");
                    return 99;
                }

                string rdpPath = args[0].Trim('"');
                Verbose("RdpSignTool v1.0 starting");

                // ---- Step 1: Validate RDP file exists -------------------------
                Verbose("RdpPath = " + rdpPath);
                if (!File.Exists(rdpPath))
                {
                    Console.Error.WriteLine("RdpSignTool: ERROR: File not found: " + rdpPath);
                    return 2;
                }

                // ---- Step 2: Find the signing cert ----------------------------
                Verbose("Looking for signing certificate...");
                X509Certificate2 cert = FindSigningCert();
                if (cert == null)
                {
                    Console.Error.WriteLine("RdpSignTool: ERROR: Signing certificate not found. Run EnsureRDPSigningCert first.");
                    return 1;
                }
                string thumb8 = (cert.Thumbprint != null && cert.Thumbprint.Length >= 8)
                    ? cert.Thumbprint.Substring(0, 8) : "????";
                Verbose("Certificate found: " + cert.Subject + " (thumb=" + thumb8 + "...)");

                // ---- Step 3: Read and parse RDP file --------------------------
                Verbose("Reading RDP file...");
                byte[] inputBytes = File.ReadAllBytes(rdpPath);
                string rawText;

                // Detect UTF-16LE BOM
                if (inputBytes.Length >= 2 && inputBytes[0] == 0xFF && inputBytes[1] == 0xFE)
                {
                    rawText = Encoding.Unicode.GetString(inputBytes, 2, inputBytes.Length - 2);
                    Verbose("Detected UTF-16LE encoding (BOM present)");
                }
                else
                {
                    rawText = Encoding.UTF8.GetString(inputBytes);
                    Verbose("Detected UTF-8 encoding (no BOM)");
                }

                // Split into lines (handle \r\r\n, \r\n, \r, \n)
                string[] inputLines = rawText.Split(
                    new[] { "\r\r\n", "\r\n", "\r", "\n" },
                    StringSplitOptions.RemoveEmptyEntries);
                Verbose("Parsed " + inputLines.Length + " lines");

                // ---- Step 4: Build field map ----------------------------------
                var fieldMap = new Dictionary<string, FieldEntry>(StringComparer.OrdinalIgnoreCase);
                foreach (string line in inputLines)
                {
                    Match match = Regex.Match(line, @"^(.+?):(.):(.*?)$");
                    if (match.Success)
                    {
                        string key = match.Groups[1].Value.Trim().ToLowerInvariant();
                        FieldEntry entry;
                        entry.Name = match.Groups[1].Value.Trim();
                        entry.Type = match.Groups[2].Value[0];
                        entry.Value = match.Groups[3].Value;
                        fieldMap[key] = entry;
                    }
                }

                if (!fieldMap.ContainsKey("full address"))
                {
                    Console.Error.WriteLine("RdpSignTool: ERROR: Missing required 'full address' field in RDP file.");
                    return 3;
                }
                Verbose("Field map built with " + fieldMap.Count + " entries");

                // ---- Step 5: Build base lines (strip old signscope/signature) --
                var baseLines = new List<string>();
                foreach (string line in inputLines)
                {
                    string lineTrimmed = line.Trim();
                    if (string.IsNullOrEmpty(lineTrimmed))
                        continue;

                    Match binaryMatch = Regex.Match(lineTrimmed, @"^(.+?):b:(.*)$");
                    if (binaryMatch.Success)
                    {
                        string key = binaryMatch.Groups[1].Value.Trim().ToLowerInvariant();
                        if (!StripKeys.Contains(key))
                            baseLines.Add(binaryMatch.Groups[1].Value.Trim() + ":b:" + binaryMatch.Groups[2].Value.Trim().ToUpperInvariant());
                        // Binary fields (password 51:b) are NEVER in signscope
                    }
                    else
                    {
                        Match fieldMatch = Regex.Match(lineTrimmed, @"^(.+?):");
                        if (fieldMatch.Success)
                        {
                            string key = fieldMatch.Groups[1].Value.Trim().ToLowerInvariant();
                            if (!StripKeys.Contains(key))
                                baseLines.Add(lineTrimmed);
                        }
                        else
                        {
                            // Skip orphaned lines that look like bare base64 data
                            // (e.g. old signature continuation without 'signature:s:' prefix).
                            // These are artifacts from previous signings that used a different
                            // wrapping format.  Valid RDP fields always have a colon.
                            if (lineTrimmed.IndexOf(':') < 0)
                            {
                                // Pure base64 chars: A-Za-z0-9+/=
                                bool looksLikeBase64 = true;
                                for (int ci = 0; ci < lineTrimmed.Length; ci++)
                                {
                                    char c = lineTrimmed[ci];
                                    if (!((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                                          (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '='))
                                    {
                                        looksLikeBase64 = false;
                                        break;
                                    }
                                }
                                if (!looksLikeBase64)
                                    baseLines.Add(lineTrimmed);
                                // else: skip — it's orphaned base64 signature data
                            }
                            else
                            {
                                baseLines.Add(lineTrimmed);
                            }
                        }
                    }
                }
                Verbose("Built " + baseLines.Count + " base lines (stripped old signature)");

                // ---- Step 6: Build canonical signscope ------------------------
                string altFullAddress = fieldMap["full address"].Value;

                // Override alternate full address in the field map so the canonical
                // signscope always includes the correct value, even when the input
                // file is missing this field (e.g. newly-created shortcuts that
                // have never been signed before).  This matches the legacy PS
                // implementation and avoids a mismatch where the output file
                // receives alternate full address = fullAddress but the signature
                // was computed with alternate full address = "".
                FieldEntry altEntry;
                altEntry.Name = "alternate full address";
                altEntry.Type = 's';
                altEntry.Value = altFullAddress;
                fieldMap["alternate full address"] = altEntry;

                // Build signscope from Microsoft's canonical field list.
                // Only include fields that actually exist in the file body.
                // This matches rdpsign.exe behavior exactly — same fields, same canonical order.
                var effectiveScopeFields = new List<string>();
                foreach (CanonicalFieldInfo cfi in CANONICAL_SIGNSCOPE)
                {
                    if (fieldMap.ContainsKey(cfi.Key))
                        effectiveScopeFields.Add(cfi.DisplayName);
                }
                string effectiveSignscope = string.Join(",", effectiveScopeFields);

                string[] scopeFields = effectiveSignscope.Split(',');

                StringBuilder sb = new StringBuilder();
                foreach (string sf in scopeFields)
                {
                    string key = sf.Trim().ToLowerInvariant();
                    string typ;
                    string val;

                    FieldEntry entry;
                    char mappedType;
                    if (fieldMap.TryGetValue(key, out entry))
                    {
                        typ = entry.Type.ToString();
                        val = entry.Value;
                    }
                    else if (FieldTypeMap.TryGetValue(key, out mappedType))
                    {
                        typ = mappedType.ToString();
                        val = (mappedType == 's') ? "" : "0";
                    }
                    else
                    {
                        // Unknown field - skip
                        continue;
                    }

                    sb.Append(key + ":" + typ + ":" + val + "\r\n");
                }
                sb.Append("signscope:s:" + effectiveSignscope + "\r\n");
                sb.Append('\0'); // null terminator

                byte[] canonicalBytes = Encoding.Unicode.GetBytes(sb.ToString());
                Verbose("Canonical signscope built (" + canonicalBytes.Length + " bytes)");

                // ---- Step 7: Sign via CryptSignMessage ------------------------
                Verbose("Calling CryptSignMessage...");
                byte[] cmsBytes = SignDetached(canonicalBytes, cert);
                Verbose("CMS signature produced (" + cmsBytes.Length + " bytes)");

                // ---- Step 8: Build output RDP content -------------------------
                byte[] header = { 0x01, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00 };
                byte[] sigBlob = Combine(header, BitConverter.GetBytes((uint)cmsBytes.Length), cmsBytes);
                string b64Raw = Convert.ToBase64String(sigBlob);

                // Wrap base64: insert two spaces after every 64 characters, keeping
                // the ENTIRE signature value on ONE RDP file line (matching rdpsign.exe
                // and the original PowerShell implementation exactly).
                // Regex equivalent: .Replace(b64Raw, '.{1,64}', '$0  ')
                StringBuilder b64Wrapped = new StringBuilder(b64Raw.Length + (b64Raw.Length / 64 + 1) * 2);
                for (int i = 0; i < b64Raw.Length; i += 64)
                {
                    int len = Math.Min(64, b64Raw.Length - i);
                    b64Wrapped.Append(b64Raw, i, len);
                    b64Wrapped.Append("  "); // two-space separator — stays on same line
                }
                string sigB64 = b64Wrapped.ToString().TrimEnd(' ');

                // Build output lines
                var outLines = new List<string>(baseLines);
                outLines.Add("alternate full address:s:" + altFullAddress);
                outLines.Add("signscope:s:" + effectiveSignscope);
                outLines.Add("signature:s:" + sigB64);

                string outText = string.Join("\r\r\n", outLines) + "\r\r\n";
                byte[] outBytes = Combine(
                    new byte[] { 0xFF, 0xFE },  // UTF-16LE BOM
                    Encoding.Unicode.GetBytes(outText));

                // ---- Step 9: Write signed RDP file ---------------------------
                Verbose("Writing signed RDP file (" + outBytes.Length + " bytes)...");
                File.WriteAllBytes(rdpPath, outBytes);

                Verbose("RdpSignTool completed successfully in " + sw.ElapsedMilliseconds + "ms");
                return 0;
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine("RdpSignTool: ERROR: " + ex.GetType().Name + ": " + ex.Message);
                if (ex.InnerException != null)
                    Console.Error.WriteLine("RdpSignTool: INNER: " + ex.InnerException.Message);
                Console.Error.WriteLine("RdpSignTool: STACK: " + ex.StackTrace);
                return 5;
            }
        }

        // ---- Helpers ---------------------------------------------------------

        private static X509Certificate2 FindSigningCert()
        {
            X509Store store = new X509Store(StoreName.My, StoreLocation.LocalMachine);
            try
            {
                store.Open(OpenFlags.OpenExistingOnly | OpenFlags.ReadOnly);
                foreach (X509Certificate2 cert in store.Certificates)
                {
                    if (string.Equals(cert.Subject, CERT_SUBJECT, StringComparison.OrdinalIgnoreCase))
                        return cert;
                }
            }
            finally
            {
                store.Close();
            }
            return null;
        }

        private static byte[] SignDetached(byte[] content, X509Certificate2 cert)
        {
            if (content == null) throw new ArgumentNullException("content");
            if (cert == null) throw new ArgumentNullException("cert");
            if (content.Length == 0) throw new ArgumentException("Content must not be empty.", "content");

            IntPtr certPtrArr = Marshal.AllocHGlobal(IntPtr.Size);
            try
            {
                Marshal.WriteIntPtr(certPtrArr, cert.Handle);

                CRYPT_SIGN_MESSAGE_PARA para = new CRYPT_SIGN_MESSAGE_PARA();
                para.cbSize = (uint)Marshal.SizeOf(typeof(CRYPT_SIGN_MESSAGE_PARA));
                para.dwMsgEncodingType = MSG_ENCODING;
                para.pSigningCert = cert.Handle;
                para.HashAlgorithm = new CRYPT_ALGORITHM_IDENTIFIER();
                para.HashAlgorithm.pszObjId = "2.16.840.1.101.3.4.2.1"; // SHA-256
                para.cMsgCert = 1u;
                para.rgpMsgCert = certPtrArr;

                GCHandle handle = GCHandle.Alloc(content, GCHandleType.Pinned);
                try
                {
                    IntPtr contentPtr = handle.AddrOfPinnedObject();
                    IntPtr[] rgpb = { contentPtr };
                    uint[] rgcb = { (uint)content.Length };

                    // Query size
                    uint cbBlob = 0;
                    if (!CryptSignMessage(ref para, true, 1u, rgpb, rgcb, null, ref cbBlob))
                    {
                        int err = Marshal.GetLastWin32Error();
                        throw new Win32Exception(err, "CryptSignMessage size query failed (error " + err + ")");
                    }

                    if (cbBlob == 0)
                        throw new Win32Exception(0, "CryptSignMessage returned zero-size output buffer.");

                    // Produce signature
                    byte[] blob = new byte[cbBlob];
                    if (!CryptSignMessage(ref para, true, 1u, rgpb, rgcb, blob, ref cbBlob))
                    {
                        int err = Marshal.GetLastWin32Error();
                        throw new Win32Exception(err, "CryptSignMessage failed (error " + err + ")");
                    }

                    if (cbBlob == blob.Length)
                        return blob;

                    byte[] trimmed = new byte[cbBlob];
                    Buffer.BlockCopy(blob, 0, trimmed, 0, (int)cbBlob);
                    return trimmed;
                }
                finally
                {
                    if (handle.IsAllocated)
                        handle.Free();
                }
            }
            finally
            {
                Marshal.FreeHGlobal(certPtrArr);
            }
        }

        private static byte[] Combine(params byte[][] arrays)
        {
            int total = 0;
            for (int i = 0; i < arrays.Length; i++)
                total += arrays[i].Length;

            byte[] result = new byte[total];
            int offset = 0;
            for (int i = 0; i < arrays.Length; i++)
            {
                Buffer.BlockCopy(arrays[i], 0, result, offset, arrays[i].Length);
                offset += arrays[i].Length;
            }
            return result;
        }

        [Conditional("DEBUG")]
        private static void Verbose(string message)
        {
            // Writes to stderr so they don't interfere with stdout (not used here)
            Console.Error.WriteLine("RdpSignTool: " + message);
        }

        private struct FieldEntry
        {
            public string Name;
            public char Type;
            public string Value;
        }

        private struct CanonicalFieldInfo
        {
            public string Key;
            public string DisplayName;
            public CanonicalFieldInfo(string key, string displayName)
            {
                Key = key;
                DisplayName = displayName;
            }
        }
    }
}
